# Apply XP/Badge widget, love icon, and script tag to all HTML files\n# Save as apply_widget_and_icon.ps1\n\n$projectRoot = "C:/Users/Anandhy/.gemini/antigravity/brain/c121de7d-7cc6-4557-bdcc-98d49362770c"\n\nGet-ChildItem -Path $projectRoot -Filter *.html -Recurse | ForEach-Object {\n    $file = $_.FullName\n    $content = Get-Content $file -Raw\n    $modified = $false\n\n    # 1. Insert widget in navbar before nav-auth if not present\n    if ($content -notmatch "id=\"xpBadgeWidget\"") {\n        $pattern = "(<div class=\"nav-auth\" id=\"navAuth\">)"\n        $widget = "<a href=\"badges.html\" id=\"xpBadgeWidget\" class=\"xp-badge-widget\"><span id=\"xpCount\">0 XP</span><span id=\"widgetBadges\" class=\"widget-badges\"></span></a>`n        "\n        $content = $content -replace $pattern, "$widget`$1"\n        $modified = $true\n    }\n\n    # 2. Insert widget in footer after footer-brand block (before footer-links)\n    if ($content -notmatch "<a href=\"badges.html\" id=\"xpBadgeWidget\"") {\n        $footerPattern = "(</div>\s*<!--?\s*footer-brand\s*-->\s*</div>\s*)(<div class=\"footer-links\")"\n        $footerWidget = "<a href=\"badges.html\" id=\"xpBadgeWidget\" class=\"xp-badge-widget\"><span id=\"xpCount\">0 XP</span><span id=\"widgetBadges\" class=\"widget-badges\"></span></a>`n        "\n        $content = $content -replace $footerPattern, "$1$footerWidget`$2"\n        $modified = $true\n    }\n\n    # 3. Replace heart emoji with love icon\n    $heartPattern = "Created with ❤️ by <strong>A\. SHAM SHARAN</strong>"\n    $loveReplacement = "Created with <img src=\"assets/love_icon.svg\" alt=\"love\" class=\"love-icon\"> by <strong>A. SHAM SHARAN</strong>"\n    if ($content -match $heartPattern) {\n        $content = $content -replace $heartPattern, $loveReplacement\n        $modified = $true\n    }\n\n    # 4. Ensure script tag before </body>\n    if ($content -notmatch "<script src=\"js/header-widget.js\"") {\n        $content = $content -replace "</body>", "<script src=\"js/header-widget.js\"></script>`n</body>"\n        $modified = $true\n    }\n\n    if ($modified) {\n        Set-Content -Path $file -Value $content -Encoding UTF8\n        Write-Host "Updated $file"\n    }\n}\n\nWrite-Host "All HTML files processed."
